#include <stdio.h>
#include <string.h>

// dp[pos][cnt][tight][started]
// pos: current position (0-indexed from left)
// cnt: number of non-zero digits placed so far
// tight: whether we are bound by the prefix of N
// started: whether we have placed any non-zero digit yet
long long dp[20][20][2][2];
char digits[20];
int len, K;

long long solve(int pos, int cnt, int tight, int started) {
    if (pos == len) {
        // ended: count if exactly K non-zero digits and number > 0
        return (cnt == K && started) ? 1 : 0;
    }
    if (dp[pos][cnt][tight][started] != -1) {
        return dp[pos][cnt][tight][started];
    }

    int limit = tight ? (digits[pos] - '0') : 9;
    long long res = 0;

    for (int d = 0; d <= limit; d++) {
        int new_started = started || (d != 0);
        int new_cnt = cnt;
        if (new_started && d != 0) {
            new_cnt++;
        }
        if (new_cnt > K) continue; // prune

        res += solve(pos + 1, new_cnt, tight && (d == limit), new_started);
    }

    dp[pos][cnt][tight][started] = res;
    return res;
}

int main() {
    long long N;
    scanf("%lld %d", &N, &K);

    // Convert N to string
    sprintf(digits, "%lld", N);
    len = strlen(digits);

    // Initialize dp with -1
    memset(dp, -1, sizeof(dp));

    long long result = solve(0, 0, 1, 0);
    printf("%lld\n", result);

    return 0;
}

