long long dp(int pos, int rem_k, int tight, int started) {
    if (pos == n_digits) {
        if (!started) return 0; // number is 0, not counted
        return (rem_k == 0) ? 1 : 0;
    }

    if (memo[pos][rem_k][tight][started] != -1)
        return memo[pos][rem_k][tight][started];

    int limit = tight ? (digits[pos] - '0') : 9;
    long long result = 0;

    for (int d = 0; d <= limit; d++) {
        int new_tight = tight && (d == limit);
        int new_started = started || (d != 0);
        int new_rem_k = rem_k;

        if (!started && d == 0) {
            // leading zero, don't count as non-zero digit
            result += dp(pos + 1, rem_k, new_tight, 0);
        } else {
            // we've started or d != 0
            if (d != 0) {
                if (rem_k > 0)
                    result += dp(pos + 1, rem_k - 1, new_tight, 1);
                // if rem_k == 0, can't place non-zero digit
            } else {
                // d == 0 and started
                result += dp(pos + 1, rem_k, new_tight, 1);
            }
        }
    }

    memo[pos][rem_k][tight][started] = result;
    return result;
}

