typedef long long ll;

int main(void) {
    char N[105];
    int K;

    if (scanf("%s %d", N, &K) != 2) return 0;

    int len = (int)strlen(N);

    // dp[pos][count][tight]
    // pos   : processed first pos digits
    // count : number of non-zero digits used so far
    // tight : 1 if prefix is equal to N's prefix, 0 if already smaller
    ll dp[105][5][2] = {0};

    dp[0][0][1] = 1;

    for (int pos = 0; pos < len; pos++) {
        int limit_digit = N[pos] - '0';
        for (int cnt = 0; cnt <= K; cnt++) {
            for (int tight = 0; tight <= 1; tight++) {
                ll cur = dp[pos][cnt][tight];
                if (cur == 0) continue;

                int limit = tight ? limit_digit : 9;
                for (int d = 0; d <= limit; d++) {
                    int ncnt = cnt + (d != 0);
                    if (ncnt > K) continue;
                    int ntight = (tight && d == limit_digit) ? 1 : 0;
                    dp[pos + 1][ncnt][ntight] += cur;
                }
            }
        }
    }

    ll ans = dp[len][K][0] + dp[len][K][1];
    printf("%lld\n", ans);

    return 0;
}

