long long dp[20][2][20]; // dp[pos][tight][nonZeroCount]

long long solve(const string &digits, int pos, int tight, int nonZeroCount, int K) {
    if (nonZeroCount > K) return 0;
    if (pos == (int)digits.size()) {
        return (nonZeroCount == K) ? 1 : 0;
    }
    if (dp[pos][tight][nonZeroCount] != -1) {
        return dp[pos][tight][nonZeroCount];
    }

    int limit = tight ? (digits[pos] - '0') : 9;
    long long ans = 0;
    for (int d = 0; d <= limit; ++d) {
        int newTight = tight && (d == limit);
        int newNonZero = nonZeroCount + (d != 0 ? 1 : 0);
        ans += solve(digits, pos + 1, newTight, newNonZero, K);
    }
    dp[pos][tight][nonZeroCount] = ans;
    return ans;
}

