// dp[pos][count][tight][started]
// But we can do it recursively with memoization

long long memo[12][12][2][2];
bool visited[12][12][2][2];

long long solve(int pos, int count, bool tight, bool started) {
    if (pos == (int)N.size()) {
        if (!started) return 0; // no digits placed (empty = 0, not valid)
        return (count == K) ? 1 : 0;
    }

    if (visited[pos][count][tight][started]) {
        return memo[pos][count][tight][started];
    }

    visited[pos][count][tight][started] = true;

    int limit = tight ? (N[pos] - '0') : 9;
    long long result = 0;

    for (int d = 0; d <= limit; d++) {
        bool new_tight = tight && (d == limit);
        bool new_started = started || (d != 0);
        int new_count = count;
        if (new_started && d != 0) new_count++;
        else if (!started && d == 0) {
            // leading zero, don't count
            new_count = 0;
        }
        // Wait, if started and d==0, we don't increment count
        // if !started and d==0, still not started

        result += solve(pos + 1, new_count, new_tight, new_started);
    }

    memo[pos][count][tight][started] = result;
    return result;
}

