import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String N = sc.next();
        int K = sc.nextInt();
        sc.close();

        int len = N.length();
        int[][] comb = new int[len + 1][len + 1];
        for (int i = 0; i <= len; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        long ans = 0;
        int nonZeroCount = 0;

        for (int i = 0; i < len; i++) {
            int digit = N.charAt(i) - '0';
            int remaining = len - i - 1;

            if (digit > 0) {
                // choose 0 for this digit
                if (K - nonZeroCount >= 0) {
                    ans += countNumbers(remaining, K - nonZeroCount, comb);
                }
                // choose 1..(digit-1) for this digit
                if (digit > 1) {
                    int need = K - nonZeroCount - 1;
                    if (need >= 0) {
                        ans += (digit - 1) * countNumbers(remaining, need, comb);
                    }
                }
                // exactly digit
                nonZeroCount++;
                if (nonZeroCount > K) break;
            }
        }

        if (nonZeroCount == K) ans++;

        System.out.println(ans);
    }

    static long countNumbers(int len, int nonZero, int[][] comb) {
        if (nonZero < 0 || nonZero > len) return 0;
        long result = comb[len][nonZero] * (long) Math.pow(9, nonZero);
        return result;
    }
}

