    static int K;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        K = sc.nextInt();

        String s = Long.toString(N);
        digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }

        int n = digits.length;
        // memo[pos][count][tight]
        memo = new long[n][K + 2][2];
        for (long[][] a : memo) for (long[] b : a) Arrays.fill(b, -1);

        long ans = solve(0, 0, 1);
        // subtract 0 if K == 0 (but problem asks 1 to N, and 0 has 0 non-zero digits)
        // Actually we count from 1, but our DP counts from 0 to N
        // If K == 0, the only number with 0 non-zero digits is 0, which we exclude
        if (K == 0) ans = 0; // no number from 1 to N has 0 non-zero digits

        System.out.println(ans);
    }

    static long solve(int pos, int count, int tight) {
        if (count > K) return 0;
        if (pos == digits.length) {
            return count == K ? 1 : 0;
        }

        if (memo[pos][count][tight] != -1) return memo[pos][count][tight];

        int limit = tight == 1 ? digits[pos] : 9;
        long res = 0;

        for (int d = 0; d <= limit; d++) {
            int newCount = count + (d != 0 ? 1 : 0);
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            res += solve(pos + 1, newCount, newTight);
        }

        memo[pos][count][tight] = res;
        return res;
    }
}

