def solve():
    import sys, math
    input_data = sys.stdin.read().strip().split()
    N = int(input_data[0])
    K = int(input_data[1])

    digits = list(map(int, str(N)))
    L = len(digits)

    # Precompute combinations C(n, k)
    C = [[0]*(L+1) for _ in range(L+1)]
    for i in range(L+1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = C[i-1][j-1] + C[i-1][j]

    # Count numbers with exactly k non-zero digits in an n-digit number (leading zeros allowed)
    # That is: choose k positions out of n, each chosen position gets 1..9 (9 choices)
    def count_exact(n, k):
        if k > n:
            return 0
        return C[n][k] * (9 ** k)

    ans = 0
    non_zero_used = 0

    for i, d in enumerate(digits):
        remaining = L - i - 1
        # Try placing a digit smaller than d at this position
        for digit in range(0, d):
            if digit == 0:
                # place zero: non-zero count unchanged
                need = K - non_zero_used
                if need >= 0:
                    ans += count_exact(remaining, need)
            else:
                # place non-zero: increase count
                need = K - non_zero_used - 1
                if need >= 0:
                    ans += count_exact(remaining, need)

        # Now fix current digit as d
        if d != 0:
            non_zero_used += 1
        if non_zero_used > K:
            break
    else:
        # If we successfully processed all digits without breaking, N itself counts
        if non_zero_used == K:
            ans += 1

    print(ans)

